CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY AUTOINCREMENT, usuario VARCHAR(80) NOT NULL UNIQUE, nombre VARCHAR(120) NOT NULL, dni VARCHAR(8) NOT NULL, rol VARCHAR(20) NOT NULL, password_hash VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS tokens (token_hash VARCHAR(64) PRIMARY KEY, usuario_id INTEGER NOT NULL, expires_at BIGINT NOT NULL, FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS establecimientos (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid VARCHAR(100) NOT NULL UNIQUE, codigo VARCHAR(100) NOT NULL UNIQUE, ruc VARCHAR(11) NOT NULL, agente VARCHAR(180) NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, actualizado VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS fiscalizaciones (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid VARCHAR(100) NOT NULL UNIQUE, expediente VARCHAR(28) NOT NULL UNIQUE, establecimiento_id INTEGER NOT NULL, usuario_id INTEGER NOT NULL, estado VARCHAR(20) NOT NULL, fecha VARCHAR(10) NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, actualizado VARCHAR(30) NOT NULL, FOREIGN KEY(establecimiento_id) REFERENCES establecimientos(id), FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS productos (id INTEGER PRIMARY KEY, nombre VARCHAR(120) NOT NULL, unidad VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS precios (id INTEGER PRIMARY KEY AUTOINCREMENT, fiscalizacion_id INTEGER NOT NULL, producto_id INTEGER NOT NULL, fila INTEGER NOT NULL, marca VARCHAR(18) NOT NULL, price DECIMAL(9,3), publicado DECIMAL(9,3), surtidor DECIMAL(9,3), descuento DECIMAL(9,3), UNIQUE(fiscalizacion_id,producto_id,fila), FOREIGN KEY(fiscalizacion_id) REFERENCES fiscalizaciones(id) ON DELETE CASCADE, FOREIGN KEY(producto_id) REFERENCES productos(id));
CREATE TABLE IF NOT EXISTS verificaciones (id INTEGER PRIMARY KEY AUTOINCREMENT, fiscalizacion_id INTEGER NOT NULL UNIQUE, telefono_publicado INTEGER, telefono_actualizado INTEGER, horario_publicado INTEGER, FOREIGN KEY(fiscalizacion_id) REFERENCES fiscalizaciones(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS incumplimientos_catalogo (id INTEGER PRIMARY KEY, descripcion TEXT NOT NULL, base_legal TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fiscalizacion_incumplimientos (id INTEGER PRIMARY KEY AUTOINCREMENT, fiscalizacion_id INTEGER NOT NULL, incumplimiento_id INTEGER NOT NULL, UNIQUE(fiscalizacion_id,incumplimiento_id), FOREIGN KEY(fiscalizacion_id) REFERENCES fiscalizaciones(id) ON DELETE CASCADE, FOREIGN KEY(incumplimiento_id) REFERENCES incumplimientos_catalogo(id));
CREATE TABLE IF NOT EXISTS hechos_verificados (id INTEGER PRIMARY KEY AUTOINCREMENT, fiscalizacion_incumplimiento_id INTEGER NOT NULL UNIQUE, texto TEXT NOT NULL, fecha VARCHAR(30) NOT NULL, usuario_id INTEGER NOT NULL, FOREIGN KEY(fiscalizacion_incumplimiento_id) REFERENCES fiscalizacion_incumplimientos(id) ON DELETE CASCADE, FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS observaciones (id INTEGER PRIMARY KEY AUTOINCREMENT, fiscalizacion_id INTEGER NOT NULL UNIQUE, otras TEXT NOT NULL, documentacion TEXT NOT NULL, observaciones TEXT NOT NULL, negativa TEXT NOT NULL, FOREIGN KEY(fiscalizacion_id) REFERENCES fiscalizaciones(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS firmas (id INTEGER PRIMARY KEY AUTOINCREMENT, fiscalizacion_id INTEGER NOT NULL, tipo VARCHAR(20) NOT NULL, imagen_base64 TEXT NOT NULL, fecha VARCHAR(30) NOT NULL, UNIQUE(fiscalizacion_id,tipo), FOREIGN KEY(fiscalizacion_id) REFERENCES fiscalizaciones(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS documentos (id INTEGER PRIMARY KEY AUTOINCREMENT, fiscalizacion_id INTEGER NOT NULL, nombre VARCHAR(120) NOT NULL, contenido_base64 TEXT NOT NULL, fecha VARCHAR(30) NOT NULL, FOREIGN KEY(fiscalizacion_id) REFERENCES fiscalizaciones(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS historial (id INTEGER PRIMARY KEY AUTOINCREMENT, entidad VARCHAR(30) NOT NULL, entidad_uuid VARCHAR(100) NOT NULL, accion VARCHAR(30) NOT NULL, usuario_id INTEGER NOT NULL, fecha VARCHAR(30) NOT NULL, detalle TEXT NOT NULL, FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
